using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace LanScope;
public sealed class DisplaySettingsWindow : Window
{
    public DisplaySettingsWindow(UiLayoutOptions initial,Action<UiLayoutOptions> changed,bool admin,Action<string,string> changePassword)
    {
        Title="DRAS · 설정";Width=610;Height=700;MinWidth=460;MinHeight=460;ResizeMode=ResizeMode.CanResizeWithGrip;Background=new SolidColorBrush(Color.FromRgb(243,246,250));FontSize=13;
        var tabs=new TabControl{Margin=new Thickness(20)};Content=tabs;var value=initial;var refresh=new List<Action<UiLayoutOptions>>();bool updating=false;
        StackPanel Tab(string name,string explanation){var p=new StackPanel{Margin=new Thickness(22)};p.Children.Add(new TextBlock{Text=explanation,TextWrapping=TextWrapping.Wrap,Foreground=Brushes.SlateGray});tabs.Items.Add(new TabItem{Header=name,ToolTip=explanation,Content=new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}});return p;}
        var fonts=Tab("글자 크기","영역별로 글자 크기를 조절합니다. 변경 사항은 즉시 적용됩니다.");var layout=Tab("배치·입력란","목록의 폭과 시험 기록명 입력란 크기를 조절합니다. 시험 기록명 입력란 모서리도 끌어 크기를 바꿀 수 있습니다.");
        void Add(StackPanel panel,string label,int min,int max,Func<UiLayoutOptions,int> get,Func<UiLayoutOptions,int,UiLayoutOptions> set){var text=new TextBlock{Margin=new Thickness(0,18,0,8)};var slider=new Slider{Minimum=min,Maximum=max,Value=get(value),TickFrequency=1,IsSnapToTickEnabled=true,ToolTip=label+" 값을 조절합니다. 설정은 이 Windows 사용자에게 저장됩니다."};panel.Children.Add(text);panel.Children.Add(slider);text.Text=label+" · "+get(value);slider.ValueChanged+=(_,e)=>{text.Text=label+" · "+(int)e.NewValue;if(!updating){value=set(value,(int)e.NewValue);changed(value);}};refresh.Add(v=>{slider.Value=get(v);text.Text=label+" · "+get(v);});}
        Add(fonts,"본문",12,20,v=>v.Body,(v,n)=>v with{Body=n});Add(fonts,"메뉴",12,20,v=>v.Menu,(v,n)=>v with{Menu=n});Add(fonts,"표 내용",10,20,v=>v.Table,(v,n)=>v with{Table=n});Add(fonts,"표 제목",11,22,v=>v.TableHeader,(v,n)=>v with{TableHeader=n});Add(fonts,"화면 제목",20,36,v=>v.Title,(v,n)=>v with{Title=n});Add(fonts,"시험 기록명",12,36,v=>v.TestNameFont,(v,n)=>v with{TestNameFont=n});
        Add(layout,"ICD 목록 너비 (px)",180,500,v=>v.ProfileWidth,(v,n)=>v with{ProfileWidth=n});Add(layout,"NIC 목록 비율 (%)",30,75,v=>v.NicPercent,(v,n)=>v with{NicPercent=n});Add(layout,"기록명 입력란 너비 (px)",240,900,v=>v.TestNameWidth,(v,n)=>v with{TestNameWidth=n});Add(layout,"기록명 입력란 높이 (px)",56,180,v=>v.TestNameHeight,(v,n)=>v with{TestNameHeight=n});
        foreach(var panel in new[]{fonts,layout}){var reset=new Button{Content="기본 설정 복원",Margin=new Thickness(0,24,0,0),Padding=new Thickness(12),ToolTip="글자와 입력란 배치를 기본값으로 되돌립니다. ICD와 기록 폴더는 변경하지 않습니다."};panel.Children.Add(reset);reset.Click+=(_,_)=>{value=new();updating=true;foreach(var f in refresh)f(value);updating=false;changed(value);};}
        var account=Tab("계정·보안",admin?"현재 비밀번호를 확인한 뒤 관리자 비밀번호를 변경합니다. 기존 ICD 암호화 키와 데이터는 유지합니다.":"관리자 비밀번호 변경은 관리자 로그인 후 사용할 수 있습니다.");
        if(admin){PasswordBox Password(string label){account.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,22,0,8)});var box=new PasswordBox{Padding=new Thickness(12),ToolTip=label+"를 입력합니다."};account.Children.Add(box);return box;}PasswordBox current=Password("현재 비밀번호"),next=Password("새 비밀번호 (8~128자)"),confirm=Password("새 비밀번호 확인");var status=new TextBlock{TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,16,0,0)};var save=new Button{Content="관리자 비밀번호 변경",Margin=new Thickness(0,24,0,0),Padding=new Thickness(14),ToolTip="현재 비밀번호를 검증하고 새 비밀번호로 로그인하도록 저장합니다. 기존 암호화 ICD는 계속 읽을 수 있습니다."};account.Children.Add(save);account.Children.Add(status);save.Click+=(_,_)=>{try{if(next.Password!=confirm.Password)throw new ArgumentException("새 비밀번호와 확인이 다릅니다.");changePassword(current.Password,next.Password);status.Text="비밀번호 변경 완료. 다음 로그인부터 새 비밀번호를 사용하세요.";}catch(Exception e){status.Text=e.Message;}finally{current.Clear();next.Clear();confirm.Clear();}};}
    }
}
